-- Imaging anchors: 24 context-tied imaging positions get constraints.anchorSortOrder.
-- GENERATED by thebolt/proposals/2026-10-29-gen-imaging-anchors.mjs. Do not hand-edit.
--
-- Needs the engine change that reads anchorSortOrder deployed first (an older engine
-- ignores the key, so applying early is harmless). Updates constraints in place, so
-- position ids, approved logs and TOH timing are untouched. Aborts, changing nothing,
-- if any position or its anchor isn't what the clocks are expected to hold.

BEGIN;

CREATE TEMP TABLE imaging_anchor (clock text, sort_order int, cat text, anchor int, anchor_cat text) ON COMMIT DROP;
INSERT INTO imaging_anchor VALUES
  ('ES', 5, 'Recurrent Sweepers', 6, 'R1'),
  ('ES', 9, 'New-Music Sweepers', 10, 'N'),
  ('ES', 12, 'Relaunch Sweepers', 13, 'A2'),
  ('ES', 16, 'Gold 10s', 17, 'G2010'),
  ('FF', 5, 'Recurrent Sweepers', 6, 'R1'),
  ('FF', 9, 'Gold 10s', 10, 'G2010'),
  ('FF', 12, 'New Music Back', 11, 'N'),
  ('HD', 19, 'New-Music Sweepers', 20, 'N'),
  ('CO', 10, 'Gold 90s', 11, 'G1990'),
  ('CO', 15, 'Discovery Sweepers', 16, 'Discovery'),
  ('CO', 24, 'Gold Backsells', 23, 'G2010'),
  ('WW', 5, 'Gold 10s', 4, 'G2010'),
  ('WW', 11, 'Gold 90s', 10, 'G1990'),
  ('WD', 10, 'Recurrent Sweepers', 11, 'R1'),
  ('WD', 15, 'Discovery Sweepers', 16, 'Discovery'),
  ('GHa', 3, 'Gold 90s', 4, 'G1990'),
  ('GHa', 9, 'Gold Backsells', 8, 'G2010'),
  ('GHa', 22, 'Gold 00s', 21, 'G2000'),
  ('GHb', 3, 'Gold 90s', 4, 'G1990'),
  ('GHb', 9, 'Gold Backsells', 8, 'G2000'),
  ('GHb', 15, 'Heritage Backsells', 14, 'H1'),
  ('GHb', 21, 'Gold 00s', 20, 'G2000'),
  ('EM', 5, 'Gold 00s', 4, 'G2000'),
  ('EM', 10, 'Power', 11, 'A1');

CREATE TEMP TABLE imaging_anchor_ids ON COMMIT DROP AS
  SELECT p.id, a.anchor FROM imaging_anchor a
    JOIN clocks k ON k.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND k.name = a.clock
    JOIN clock_positions p ON p.clock_id = k.id AND p.sort_order = a.sort_order AND p.position_type = 'sweeper'
    JOIN categories c ON c.id = p.category_id AND c.name = a.cat
    JOIN clock_positions ap ON ap.clock_id = k.id AND ap.sort_order = a.anchor AND ap.position_type = 'category'
    JOIN categories ac ON ac.id = ap.category_id AND ac.name = a.anchor_cat;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM imaging_anchor_ids;
  IF n <> 24 THEN RAISE EXCEPTION 'only % of 24 anchored positions match the clocks: they have drifted, regenerate', n; END IF;
END $$;

UPDATE clock_positions p SET constraints = coalesce(p.constraints, '{}'::jsonb) || jsonb_build_object('anchorSortOrder', a.anchor)
FROM imaging_anchor_ids a WHERE p.id = a.id;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM clock_positions p JOIN imaging_anchor_ids a ON a.id = p.id
    WHERE (p.constraints->>'anchorSortOrder')::int = a.anchor;
  IF n <> 24 THEN RAISE EXCEPTION 'expected 24 anchored positions, got %', n; END IF;
END $$;

COMMIT;
